mapper.insert:
INSERT INTO financialdb."CT_FI_TWOMONVOUCHER" ("VC_NIANYR", "ID", "ACCOUNTNUM", "ACCOUNTNAME", "COMPANY", "CURRENCYSTD", "CURRENCY", "TORMBEXT", "BOOKEDDATE", "ACCOUNTTYPE", "ACCOUNTDETAILNUM", "ACCOUNTDETAIL", "ENTRYSEQ", "ASSISTSEQ", "DEBITAMOUNTSTD", "CREDITAMOUNTSTD", "DEBITAMOUNTRMB", "CREDITAMOUNTRMB", "CREATETIME", "FILTERDATE")
--with a as (
select #{queryDate}, --年月日 ev.id, --id eve.account_code , --科目代码 eaa.account_name , --科目名称 eoc.org_name , --公司 eeer.source_eas_code , --本位币，根据机构从金蝶下获取,写个参数表 ev.currency, eeer.exchange_rate ,--本位币转人民币汇率 ev.voucher_date , --记账日期 '合同' ,--核算项目类型 eve.contract_code, --核算项目明细编码 eve.contract_name, --核算项目明细 '1', --凭证分录行号 '1', --凭证辅助帐行号 eve.debit_amount , --借方本位币发生金额 eve.credit_amount , --贷方本位币发生金额 eve.debit_amount *eeer.exchange_rate , --借方发生金额RMB *汇率 eve.credit_amount *eeer.exchange_rate , --贷方发生金额RMB *汇率 #{queryDate}, --固化时间 #{queryDate} --筛选日期 from eg_voucher ev join eg_voucher_entry eve on ev.id = eve.voucher_id join eg_currency curr on ev.currency = curr.currency_code join eg_eas_exchange_rate eeer on curr.eas_code = eeer.source_eas_code join eg_org_company eoc on ev.org_id=eoc.org_id join eg_contract ec on eve.contract_code =ec.contract_code join (select distinct ea.account_code ,ea.account_name from eg_account ea) eaa on eaa.account_code=eve.account_code where ev.voucher_date >= to_date(#{queryDate}, 'YYYY-MM-DD') - interval '2 month' --add_months(CURRENT_DATE,-2) and eeer.execute_date = #{queryDate} and eeer.target_eas_code = 'BB01' and eve.account_code in ('1231.04.02', '1231.03.04', '1231.04.01', '1231.03.01', '1532.02', '1532.01', '1122.06', '1122.07', '1221.04', '1221.07', '1122.03', '1122.03.01', '1122.03.02', '1122.03.03', '1122.03.04', '1531.01.01', '1531.01.02', '1531.01.03', '1531.01.04', '1531.01.05', '1531.01.06', '1531.01.08', '1531.01.09', '1531.01.10', '2701.01', '2701.02', '2701.07' ) --)select count(1) from a;

insert into id_temp
select max(id) id from eg_contract_balance where period_code <= #{param.periodCode}
and org_id in
#{item}
group by contract_code, client_code, org_id, bill_contract_code
